#!/usr/bin/env node
/**
 * Build the vendorable single-file bundle:
 *
 *   dist/CamioPointer-<v>.js       one ESM file (library + MediaPipe Tasks Vision JS,
 *                                 the latter evaluated lazily), Biome-formatted with
 *                                 Audiom's own config so `biome ci .` passes on it
 *   dist/CamioPointer-<v>.d.ts     bundled declarations
 *   dist/CamioPointer-<v>.test.ts  Vitest smoke test to keep next to it (from test/dist.smoke.template.ts)
 *   dist/assets/MANIFEST.json     what the host must self-host (not copied)
 *
 * Then reports minified / gzipped size and checks: OpenCV.js not bundled, exactly one
 * dynamic import left and it is webpackIgnore'd, no import.meta, no require().
 *
 *   node scripts/build.mjs
 */

import { execFileSync } from 'node:child_process';
import { mkdirSync, readFileSync, statSync, writeFileSync, copyFileSync, rmSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { gzipSync } from 'node:zlib';
import * as esbuild from 'esbuild';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const pkg = JSON.parse(readFileSync(join(ROOT, 'package.json'), 'utf8'));
const V = pkg.version;
const MP = JSON.parse(readFileSync(join(ROOT, 'node_modules/@mediapipe/tasks-vision/package.json'), 'utf8')).version;
const OPENCV_DEP = pkg.devDependencies['@techstark/opencv-js'];
const DIST = join(ROOT, 'dist');
const NAME = `CamioPointer-${V}`;
const JS = join(DIST, `${NAME}.js`);
const DTS = join(DIST, `${NAME}.d.ts`);
const TEST = join(DIST, `${NAME}.test.ts`);
mkdirSync(join(DIST, 'assets'), { recursive: true });

const biome = join(ROOT, 'node_modules/@biomejs/biome/bin/biome');
// Audiom's biome.json (copied from upstream) with VCS integration off, so it can run here.
const biomeDir = join(ROOT, 'node_modules/.cache/camio-biome');
mkdirSync(biomeDir, { recursive: true });
const biomeCfg = JSON.parse(readFileSync(join(ROOT, 'scripts/biome.audiom.json'), 'utf8'));
biomeCfg.vcs = { enabled: false };
biomeCfg.files = { ...(biomeCfg.files || {}), ignoreUnknown: false };
writeFileSync(join(biomeDir, 'biome.json'), JSON.stringify(biomeCfg, null, '\t'));
const runBiome = (args) =>
	execFileSync(process.execPath, [biome, ...args, '--config-path', biomeDir], { cwd: ROOT, stdio: 'pipe' }).toString();

const header = (kind) => `// biome-ignore-all lint: vendored build output (CamioPointer + MediaPipe Tasks Vision); edit camio-pointer/src and rebuild
/**
 * CamioPointer ${V} — camera fingertip pointer for tactile surfaces (DOT Pad, printed maps).
 * ${kind}. GENERATED by camio-pointer/scripts/build.mjs — do not edit by hand.
 *
 * Bundles @mediapipe/tasks-vision ${MP} (Apache-2.0, (c) Google LLC), evaluated
 * lazily on the first hand-landmarker creation. Its WASM runtime and the hand
 * model are NOT bundled: self-host them (see dist/assets/MANIFEST.json) and pass
 * their location as \`assetsBase\`. OpenCV.js (@techstark/opencv-js ${OPENCV_DEP},
 * Apache-2.0) is NOT bundled either: self-host it and pass \`opencvUrl\`; it is
 * loaded only for a rect surface. Importing this module touches no camera, DOM
 * or network.
 */
`;

/* ------------------------------------------------------------- bundle -- */

const result = await esbuild.build({
	entryPoints: [join(ROOT, 'src/index.ts')],
	bundle: true,
	format: 'esm',
	platform: 'browser',
	target: 'es2020',
	minify: false,
	treeShaking: true,
	legalComments: 'inline',
	write: false,
	logLevel: 'warning',
});
let js = result.outputFiles[0].text;
js = js.replace(/^\/\/# sourceMappingURL=.*$/gm, '');

// MediaPipe loads its WASM glue with `import(url)` inside workers; webpack must not try to resolve it.
const dyn = [...js.matchAll(/\bimport\(\s*(?!\/\*\s*webpackIgnore)([^)]*\.toString\(\))\s*\)/g)];
if (dyn.length !== 1) throw new Error(`expected exactly 1 MediaPipe dynamic import, found ${dyn.length}`);
js = js.replace(dyn[0][0], `import(/* webpackIgnore: true */ ${dyn[0][1]})`);

const checks = {
	// OpenCV.js is loaded at run time from `opencvUrl` (the glue code mentions cv.Mat etc.):
	// its own body (UMD wrapper line) must never be bundled.
	opencvBundled: /root\.cv\s*=\s*factory\(\)/.test(js) || js.length > 2_000_000,
	importMeta: /import\.meta/.test(js),
	require: /\brequire\(/.test(js),
	otherDynamicImports: [...js.matchAll(/\bimport\(/g)].length !== 1,
};
for (const [k, bad] of Object.entries(checks)) if (bad) throw new Error(`bundle check failed: ${k}`);

writeFileSync(JS, `${header('Single-file ESM bundle')}\n${js}`);

/* -------------------------------------------------------------- types -- */

const tmpDts = join(biomeDir, 'index.d.ts');
execFileSync(
	process.execPath,
	[join(ROOT, 'node_modules/dts-bundle-generator/dist/bin/dts-bundle-generator.js'), '--no-banner', '--export-referenced-types=false', '-o', tmpDts, join(ROOT, 'src/index.ts')],
	{ cwd: ROOT, stdio: 'pipe' },
);
const dts = readFileSync(tmpDts, 'utf8')
	.replace(/^\/\/ Generated by dts-bundle-generator.*$/m, '')
	.replace(/^export \{\};\s*$/m, '');
writeFileSync(DTS, `${header('TypeScript declarations')}\n${dts}`);

/* --------------------------------------------------------- smoke test -- */

const tpl = readFileSync(join(ROOT, 'test/dist.smoke.template.ts'), 'utf8').replaceAll('__CAMIO_FILE__', `./${NAME}.js`).replaceAll('__CAMIO_VERSION__', V);
writeFileSync(TEST, tpl);

/* ------------------------------------------------------ format (Biome) -- */

runBiome(['format', '--write', JS, DTS, TEST]);
const ci = runBiome(['ci', JS, DTS, TEST]);
void ci;

/* ------------------------------------------------------------- assets -- */

const wasmDir = join(ROOT, 'node_modules/@mediapipe/tasks-vision/wasm');
const size = (f) => statSync(join(wasmDir, f)).size;
const manifest = {
	note: 'Files the host app must serve (same origin) under `assetsBase`. Nothing here is bundled into the JS. The WASM must be the same MediaPipe version as the bundle.',
	mediapipeTasksVision: MP,
	assetsBase: '/vendor/mediapipe/  (any URL; pass it as createCamioPointer({ assetsBase, opencvUrl }))',
	opencvJs: OPENCV_DEP,
	opencvUrl: '/vendor/opencv/opencv.js  (any URL; loaded only for a rect surface, in a Web Worker by default)',
	files: [
		...['vision_wasm_internal.js', 'vision_wasm_internal.wasm', 'vision_wasm_nosimd_internal.js', 'vision_wasm_nosimd_internal.wasm'].map((f) => ({
			path: `wasm/${f}`,
			bytes: size(f),
			source: `node_modules/@mediapipe/tasks-vision@${MP}/wasm/${f}`,
		})),
		{
			path: '../opencv/opencv.js  (i.e. vendor/opencv/opencv.js, served at opencvUrl)',
			bytes: statSync(join(ROOT, 'node_modules/@techstark/opencv-js/dist/opencv.js')).size,
			source: `node_modules/@techstark/opencv-js@${OPENCV_DEP}/dist/opencv.js (Apache-2.0)`,
		},
		{
			path: 'hand_landmarker.task',
			bytes: 'about 7.8 MB',
			source: 'https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task (Apache-2.0)',
		},
	],
	copyScript: 'node camio-pointer/scripts/copy-assets.mjs <dest>/vendor/mediapipe --opencv <dest>/vendor/opencv   (copies the WASM and opencv.js; fetches the model only with --fetch-model)',
	notNeeded: 'vision_wasm_module_internal.* (module-worker variant) is not used.',
};
writeFileSync(join(DIST, 'assets/MANIFEST.json'), `${JSON.stringify(manifest, null, '\t')}\n`);

/* ------------------------------------------------------------ report -- */

const raw = readFileSync(JS);
const min = (await esbuild.transform(raw.toString(), { minify: true, format: 'esm', target: 'es2020', legalComments: 'none' })).code;
const kb = (n) => `${(n / 1024).toFixed(1)} KB`;
const libOnly = await esbuild.build({
	entryPoints: [join(ROOT, 'src/index.ts')],
	bundle: true,
	format: 'esm',
	platform: 'browser',
	target: 'es2020',
	minify: true,
	write: false,
	external: ['@mediapipe/tasks-vision'],
	logLevel: 'silent',
});
const lib = libOnly.outputFiles[0].contents;
console.log(`${NAME}.js     ${kb(raw.length)} formatted | ${kb(min.length)} minified | ${kb(gzipSync(min).length)} min+gzip`);
console.log(`  of which CamioPointer itself: ${kb(lib.length)} minified | ${kb(gzipSync(lib).length)} min+gzip (MediaPipe JS is the rest)`);
console.log(`${NAME}.d.ts   ${kb(statSync(DTS).size)}`);
console.log(`${NAME}.test.ts ${kb(statSync(TEST).size)}`);
console.log('checks: OpenCV.js not bundled, no import.meta, no require(), one dynamic import (MediaPipe WASM glue, webpackIgnore) — ok; biome ci (Audiom config) — ok');
rmSync(tmpDts, { force: true });
void copyFileSync;
